    if (node.shadowRoot) walk(node.shadowRoot);
    if (node.nodeType === 3) {
      const value = (node.textContent || '').trim();
      if (value && /user_id|500|null value|extracted|heals_pass|error/i.test(value)) {
        texts.push(value.slice(0, 500));
      }
    }
    const children = node.childNodes || [];
    for (let i = 0; i < children.length; i++) walk(children[i]);
  };
  walk(document);
  return { found: texts.slice(-15) };
}

